lish":"rooms","thai":"ห้อง","kind":"noun","forms":["rooms"],"tokens":["rooms"]},{"word":"food","english":"food","thai":"อาหาร","kind":"noun","forms":["food"],"tokens":["food"]},{"word":"rice","english":"rice","thai":"ข้าว","kind":"noun","forms":["rice"],"tokens":["rice"]},{"word":"bread","english":"bread","thai":"ขนมปัง","kind":"noun","forms":["bread"],"tokens":["bread"]},{"word":"milk","english":"milk","thai":"นม","kind":"noun","forms":["milk"],"tokens":["milk"]},{"word":"money","english":"money","thai":"เงิน","kind":"noun","forms":["money"],"tokens":["money"]},{"word":"car","english":"car","thai":"รถยนต์","kind":"noun","forms":["car"],"tokens":["car"]},{"word":"cars","english":"cars","thai":"รถยนต์","kind":"noun","forms":["cars"],"tokens":["cars"]},{"word":"door","english":"door","thai":"ประตู","kind":"noun","forms":["door"],"tokens":["door"]},{"word":"doors","english":"doors","thai":"ประตู","kind":"noun","forms":["doors"],"tokens":["doors"]},{"word":"window","english":"window","thai":"หน้าต่าง","kind":"noun","forms":["window"],"tokens":["window"]},{"word":"windows","english":"windows","thai":"หน้าต่าง","kind":"noun","forms":["windows"],"tokens":["windows"]},{"word":"bed","english":"bed","thai":"เตียง","kind":"noun","forms":["bed"],"tokens":["bed"]},{"word":"beds","english":"beds","thai":"เตียง","kind":"noun","forms":["beds"],"tokens":["beds"]},{"word":"ball","english":"ball","thai":"ลูกบอล","kind":"noun","forms":["ball"],"tokens":["ball"]},{"word":"balls","english":"balls","thai":"ลูกบอล","kind":"noun","forms":["balls"],"tokens":["balls"]},{"word":"computer","english":"computer","thai":"คอมพิวเตอร์","kind":"noun","forms":["computer"],"tokens":["computer"]},{"word":"computers","english":"computers","thai":"คอมพิวเตอร์","kind":"noun","forms":["computers"],"tokens":["computers"]},{"word":"television","english":"television","thai":"โทรทัศน์","kind":"noun","forms":["television"],"tokens":["television"]},{"word":"televisions","english":"televisions","thai":"โทรทัศน์","kind":"noun","forms":["televisions"],"tokens":["televisions"]},{"word":"juice","english":"juice","thai":"น้ำผลไม้","kind":"noun","forms":["juice"],"tokens":["juice"]},{"word":"coffee","english":"coffee","thai":"กาแฟ","kind":"noun","forms":["coffee"],"tokens":["coffee"]},{"word":"talking","english":"talking","thai":"พูด","kind":"verb","forms":["talking"],"tokens":["talking"]},{"word":"listening","english":"listening","thai":"ฟัง","kind":"verb","forms":["listening"],"tokens":["listening"]},{"word":"driving","english":"driving","thai":"ขับรถ","kind":"verb","forms":["driving"],"tokens":["driving"]},{"word":"eating","english":"eating","thai":"กิน","kind":"verb","forms":["eating"],"tokens":["eating"]},{"word":"drinking","english":"drinking","thai":"ดื่ม","kind":"verb","forms":["drinking"],"tokens":["drinking"]},{"word":"sleeping","english":"sleeping","thai":"นอน","kind":"verb","forms":["sleeping"],"tokens":["sleeping"]},{"word":"running","english":"running","thai":"วิ่ง","kind":"verb","forms":["running"],"tokens":["running"]},{"word":"walking","english":"walking","thai":"เดิน","kind":"verb","forms":["walking"],"tokens":["walking"]},{"word":"playing","english":"playing","thai":"เล่น","kind":"verb","forms":["playing"],"tokens":["playing"]},{"word":"reading","english":"reading","thai":"อ่าน","kind":"verb","forms":["reading"],"tokens":["reading"]},{"word":"going","english":"going","thai":"ไป","kind":"verb","forms":["going"],"tokens":["going"]},{"word":"holding","english":"holding","thai":"ถือ","kind":"verb","forms":["holding"],"tokens":["holding"]},{"word":"opening","english":"opening","thai":"เปิด","kind":"verb","forms":["opening"],"tokens":["opening"]},{"word":"cleaning","english":"cleaning","thai":"ทำความสะอาด","kind":"verb","forms":["cleaning"],"tokens":["cleaning"]},{"word":"using","english":"using","thai":"ใช้","kind":"verb","forms":["using"],"tokens":["using"]},{"word":"carrying","english":"carrying","thai":"ถือไป","kind":"verb","forms":["carrying"],"tokens":["carrying"]},{"word":"finding","english":"finding","thai":"พบ","kind":"verb","forms":["finding"],"tokens":["finding"]},{"word":"buying","english":"buying","thai":"ซื้อ","kind":"verb","forms":["buying"],"tokens":["buying"]},{"word":"closing","english":"closing","thai":"ปิด","kind":"verb","forms":["closing"],"tokens":["closing"]},{"word":"wearing","english":"wearing","thai":"สวม","kind":"verb","forms":["wearing"],"tokens":["wearing"]},{"word":"putting on","english":"putting on","thai":"สวมใส่","kind":"verb","forms":["putting on"],"tokens":["putting","on"]},{"word":"taking off","english":"taking off","thai":"ถอด","kind":"verb","forms":["taking off"],"tokens":["taking","off"]},{"word":"riding","english":"riding","thai":"ขี่","kind":"verb","forms":["riding"],"tokens":["riding"]},{"word":"catching","english":"catching","thai":"ขึ้นให้ทัน","kind":"verb","forms":["catching"],"tokens":["catching"]},{"word":"getting on","english":"getting on","thai":"เคลื่อนตัว","kind":"verb","forms":["getting on"],"tokens":["getting","on"]},{"word":"helping","english":"helping","thai":"ช่วย","kind":"verb","forms":["helping"],"tokens":["helping"]},{"word":"watching","english":"watching","thai":"ดู","kind":"verb","forms":["watching"],"tokens":["watching"]},{"word":"teaching","english":"teaching","thai":"สอน","kind":"verb","forms":["teaching"],"tokens":["teaching"]},{"word":"sitting","english":"sitting","thai":"นั่ง","kind":"verb","forms":["sitting"],"tokens":["sitting"]},{"word":"standing","english":"standing","thai":"ยืน","kind":"verb","forms":["standing"],"tokens":["standing"]},{"word":"waiting","english":"waiting","thai":"รอ","kind":"verb","forms":["waiting"],"tokens":["waiting"]},{"word":"arriving","english":"arriving","thai":"มาถึง","kind":"verb","forms":["arriving"],"tokens":["arriving"]},{"word":"leaving","english":"leaving","thai":"ออกจาก","kind":"verb","forms":["leaving"],"tokens":["leaving"]},{"word":"cooking","english":"cooking","thai":"ปรุง","kind":"verb","forms":["cooking"],"tokens":["cooking"]},{"word":"taking","english":"taking","thai":"หยิบ","kind":"verb","forms":["taking"],"tokens":["taking"]},{"word":"bringing","english":"bringing","thai":"นำมา","kind":"verb","forms":["bringing"],"tokens":["bringing"]},{"word":"choosing","english":"choosing","thai":"เลือก","kind":"verb","forms":["choosing"],"tokens":["choosing"]},{"word":"cutting","english":"cutting","thai":"หั่น","kind":"verb","forms":["cutting"],"tokens":["cutting"]},{"word":"drawing","english":"drawing","thai":"วาด","kind":"verb","forms":["drawing"],"tokens":["drawing"]},{"word":"painting","english":"painting","thai":"ทาสี","kind":"verb","forms":["painting"],"tokens":["painting"]},{"word":"fixing","english":"fixing","thai":"ซ่อม","kind":"verb","forms":["fixing"],"tokens":["fixing"]},{"word":"pushing","english":"pushing","thai":"ผลัก","kind":"verb","forms":["pushing"],"tokens":["pushing"]},{"word":"pulling","english":"pulling","thai":"ดึง","kind":"verb","forms":["pulling"],"tokens":["pulling"]},{"word":"lifting","english":"lifting","thai":"ยก","kind":"verb","forms":["lifting"],"tokens":["lifting"]},{"word":"selling","english":"selling","thai":"ขาย","kind":"verb","forms":["selling"],"tokens":["selling"]},{"word":"visiting","english":"visiting","thai":"เยี่ยม","kind":"verb","forms":["visiting"],"tokens":["visiting"]},{"word":"coming","english":"coming","thai":"มา","kind":"verb","forms":["coming"],"tokens":["coming"]},{"word":"washing","english":"washing","thai":"ล้าง","kind":"verb","forms":["washing"],"tokens":["washing"]},{"word":"red","english":"red","thai":"สีแดง","kind":"adjective","forms":["red"],"tokens":["red"]},{"word":"blue","english":"blue","thai":"สีน้ำเงิน","kind":"adjective","forms":["blue"],"tokens":["blue"]},{"word":"big","english":"big","thai":"ใหญ่","kind":"adjective","forms":["big"],"tokens":["big"]},{"word":"small","english":"small","thai":"เล็ก","kind":"adjective","forms":["small"],"tokens":["small"]},{"word":"hot","english":"hot","thai":"ร้อน","kind":"adjective","forms":["hot"],"tokens":["hot"]},{"word":"cold","english":"cold","thai":"เย็น","kind":"adjective","forms":["cold"],"tokens":["cold"]},{"word":"green","english":"green","thai":"สีเขียว","kind":"adjective","forms":["green"],"tokens":["green"]},{"word":"yellow","english":"yellow","thai":"สีเหลือง","kind":"adjective","forms":["yellow"],"tokens":["yellow"]},{"word":"black","english":"black","thai":"สีดำ","kind":"adjective","forms":["black"],"tokens":["black"]},{"word":"white","english":"white","thai":"สีขาว","kind":"adjective","forms":["white"],"tokens":["white"]},{"word":"tall","english":"tall","thai":"สูง","kind":"adjective","forms":["tall"],"tokens":["tall"]},{"word":"short","english":"short","thai":"เตี้ย","kind":"adjective","forms":["short"],"tokens":["short"]},{"word":"clean","english":"clean","thai":"สะอาด","kind":"adjective","forms":["clean"],"tokens":["clean"]},{"word":"dirty","english":"dirty","thai":"สกปรก","kind":"adjective","forms":["dirty"],"tokens":["dirty"]},{"word":"wet","english":"wet","thai":"เปียก","kind":"adjective","forms":["wet"],"tokens":["wet"]},{"word":"dry","english":"dry","thai":"แห้ง","kind":"adjective","forms":["dry"],"tokens":["dry"]},{"word":"new","english":"new","thai":"ใหม่","kind":"adjective","forms":["new"],"tokens":["new"]},{"word":"old","english":"old","thai":"เก่า","kind":"adjective","forms":["old"],"tokens":["old"]},{"word":"full","english":"full","thai":"เต็ม","kind":"adjective","forms":["full"],"tokens":["full"]},{"word":"empty","english":"empty","thai":"ว่างเปล่า","kind":"adjective","forms":["empty"],"tokens":["empty"]},{"word":"open","english":"open","thai":"เปิดอยู่","kind":"adjective","forms":["open"],"tokens":["open"]},{"word":"closed","english":"closed","thai":"ปิดอยู่","kind":"adjective","forms":["closed"],"tokens":["closed"]},{"word":"heavy","english":"heavy","thai":"หนัก","kind":"adjective","forms":["heavy"],"tokens":["heavy"]},{"word":"light","english":"light","thai":"เบา","kind":"adjective","forms":["light"],"tokens":["light"]},{"word":"happy","english":"happy","thai":"มีความสุข","kind":"adjective","forms":["happy"],"tokens":["happy"]},{"word":"sad","english":"sad","thai":"เศร้า","kind":"adjective","forms":["sad"],"tokens":["sad"]},{"word":"fast","english":"fast","thai":"เร็ว","kind":"adjective","forms":["fast"],"tokens":["fast"]},{"word":"slow","english":"slow","thai":"ช้า","kind":"adjective","forms":["slow"],"tokens":["slow"]},{"word":"soft","english":"soft","thai":"นุ่ม","kind":"adjective","forms":["soft"],"tokens":["soft"]},{"word":"hard","english":"hard","thai":"แข็ง","kind":"adjective","forms":["hard"],"tokens":["hard"]},{"word":"thick","english":"thick","thai":"หนา","kind":"adjective","forms":["thick"],"tokens":["thick"]},{"word":"thin","english":"thin","thai":"บาง","kind":"adjective","forms":["thin"],"tokens":["thin"]},{"word":"pink","english":"pink","thai":"สีชมพู","kind":"adjective","forms":["pink"],"tokens":["pink"]},{"word":"purple","english":"purple","thai":"สีม่วง","kind":"adjective","forms":["purple"],"tokens":["purple"]},{"word":"brown","english":"brown","thai":"สีน้ำตาล","kind":"adjective","forms":["brown"],"tokens":["brown"]}]'; choice jsonb; target uuid; n integer;
begin
 select * into s from public.english_class_sessions where id=p_session and created_at>now()-interval '18 hours' for update;
 if not found then raise exception 'Class has ended. Scan the current code.';end if;
 host:=coalesce(s.host_secret_hash=md5(p_payload->>'hostSecret'),false);
 if not host and (uid is null or not exists(select 1 from public.english_class_members where session_id=s.id and learner_id=uid and active)) then raise exception 'Join this class first';end if;
 insert into public.english_drawing_games(session_id) values(s.id) on conflict do nothing;
 select * into g from public.english_drawing_games where session_id=s.id;
 if p_action in ('open','close','start','next','reveal','finish') and not host then raise exception 'Teacher controls only';end if;
 if p_action not in ('state','open','close') and coalesce((p_payload->>'round')::integer,-1)<>g.round then raise exception 'The round changed. Try again.';end if;
 if g.phase='drawing' and now()>=g.deadline then
  select artist into target from public.english_drawings where session_id=s.id and round=g.round order by position limit 1;
  update public.english_drawing_games set phase='guessing',artist=target where session_id=s.id returning * into g;
 end if;
 if p_action='open' then update public.english_drawing_games set active=true where session_id=s.id;
 elsif p_action='close' then update public.english_drawing_games set active=false where session_id=s.id;
 elsif p_action='start' then
  if g.phase not in ('lobby','results') then raise exception 'Finish this round first';end if;
  if (select count(*) from public.english_class_members where session_id=s.id and active)<1 then raise exception 'No students in this class';end if;
  n:=coalesce((p_payload->>'seconds')::integer,60);if n not in (30,60,90,120) then raise exception 'Choose a drawing time';end if;
  for member_row in select learner_id from public.english_class_members where session_id=s.id and active order by random() loop
   -- A private content-word prompt, seen by every active player; no grammar fallback.
   select v.value into choice from jsonb_array_elements(words) v
   where v.value->>'kind' in ('noun','verb','adjective') and jsonb_array_length(v.value->'tokens')>0
   and not exists(select 1 from public.english_class_members participant where participant.session_id=s.id and participant.active and exists(
    select 1 from jsonb_array_elements_text(v.value->'tokens') token where not exists(
     select 1 from public.english_word_progress p where p.learner_id=participant.learner_id and p.word_id='en:'||token and (coalesce(p.exposure_count,0)>0 or p.attempts>0))))
   order by exists(select 1 from public.english_drawings d where d.session_id=s.id and d.round=g.round+1 and d.thai=v.value->>'thai'),
     exists(select 1 from public.english_drawings d where d.session_id=s.id and d.artist=member_row.learner_id and d.round=g.round and d.thai=v.value->>'thai'),random() limit 1;
   if choice is null then raise exception 'No shared seen nouns, verbs or adjectives. Practise some words together before starting the game.';end if;
   insert into public.english_drawings(session_id,round,artist,position,thai,english) values(s.id,g.round+1,member_row.learner_id,i,choice->>'thai',choice->>'english');i:=i+1;
  end loop;
  update public.english_drawing_games set active=true,round=round+1,phase='drawing',deadline=now()+make_interval(secs=>n),artist=null,revealed=false where session_id=s.id;
 elsif p_action in ('save','complete') then
  -- The session row is locked above: concurrent finishes receive distinct ranks.
  if exists(select 1 from public.english_drawings where session_id=s.id and round=g.round and artist=uid and finish_rank is not null) then
   null; -- Safe retry; a finished drawing and its bonus cannot change.
  else
   if g.phase<>'drawing' then raise exception 'Drawing time has ended';end if;
   if coalesce(p_payload->>'picture','') !~ '^data:image/png;base64,[A-Za-z0-9+/=]+$' or length(p_payload->>'picture')>150000 then raise exception 'Invalid drawing';end if;
   if not exists(select 1 from public.english_drawings where session_id=s.id and round=g.round and artist=uid) then raise exception 'Join the next round';end if;
   if p_action='complete' then
    select coalesce(max(finish_rank),0)+1 into n from public.english_drawings where session_id=s.id and round=g.round;
    update public.english_drawings set picture=p_payload->>'picture',finish_rank=n,finish_bonus=greatest(0,4-n),finished_at=clock_timestamp() where session_id=s.id and round=g.round and artist=uid;
    if not exists(select 1 from public.english_drawings where session_id=s.id and round=g.round and finish_rank is null) then
     select artist into target from public.english_drawings where session_id=s.id and round=g.round order by position limit 1;
     update public.english_drawing_games set phase='guessing',artist=target where session_id=s.id;
    end if;
   else
    update public.english_drawings set picture=p_payload->>'picture' where session_id=s.id and round=g.round and artist=uid;
   end if;
  end if;
 elsif p_action='award' then
  if g.phase<>'guessing' or g.artist is distinct from uid or g.revealed or g.artist::text is distinct from p_payload->>'artist' then raise exception 'Only the current artist can award this point';end if;
  target:=(p_payload->>'learner')::uuid;
  if target=uid or not exists(select 1 from public.english_drawings where session_id=s.id and round=g.round and artist=target) then raise exception 'Choose another player';end if;
  update public.english_drawings set awarded=target where session_id=s.id and round=g.round and artist=uid and awarded is null;
  update public.english_drawing_games set revealed=true where session_id=s.id;
 elsif p_action='reveal' then
  if g.phase<>'guessing' or g.artist::text is distinct from p_payload->>'artist' then raise exception 'Picture changed';end if;
  update public.english_drawing_games set revealed=true where session_id=s.id;
 elsif p_action='next' then
  if g.phase<>'guessing' or g.artist::text is distinct from p_payload->>'artist' then raise exception 'Picture changed';end if;
  update public.english_drawings set shown=true where session_id=s.id and round=g.round and artist=g.artist;
  select artist into target from public.english_drawings where session_id=s.id and round=g.round and not shown order by position limit 1;
  update public.english_drawing_games set artist=target,revealed=false,phase=case when target is null then 'voting' else 'guessing' end where session_id=s.id;
 elsif p_action='vote' then
  target:=(p_payload->>'artist')::uuid;
  if g.phase<>'voting' or target=uid or not exists(select 1 from public.english_drawings where session_id=s.id and round=g.round and artist=uid) or not exists(select 1 from public.english_drawings where session_id=s.id and round=g.round and artist=target and picture<>'') then raise exception 'Choose another picture';end if;
  insert into public.english_drawing_votes values(s.id,g.round,uid,target) on conflict do nothing;
 elsif p_action='finish' then
  if g.phase<>'voting' then raise exception 'Voting is not open';end if;
  insert into public.english_drawing_bonus select s.id,g.round,artist from public.english_drawing_votes where session_id=s.id and round=g.round group by artist having count(*)=(select max(v.c) from (select count(*) c from public.english_drawing_votes where session_id=s.id and round=g.round group by artist) v) on conflict do nothing;
  update public.english_drawing_games set phase='results' where session_id=s.id;
 elsif p_action<>'state' then raise exception 'Unknown game action';end if;
 select * into g from public.english_drawing_games where session_id=s.id;
 return jsonb_build_object('active',g.active,'round',g.round,'phase',g.phase,'deadline',g.deadline,'serverNow',now(),'artist',g.artist,'revealed',g.revealed,'vote',(select artist from public.english_drawing_votes where session_id=s.id and round=g.round and voter=uid),'voteCount',(select count(*) from public.english_drawing_votes where session_id=s.id and round=g.round),'drawings',coalesce((select jsonb_agg(jsonb_build_object('artist',d.artist,'name',coalesce(p.display_name,'Student'),'thai',case when d.artist=uid then d.thai end,'english',case when d.artist=uid or (g.revealed and g.artist=d.artist) or g.phase in ('voting','results') then d.english end,'picture',case when d.artist=uid or (g.phase='guessing' and d.artist=g.artist) or g.phase in ('voting','results') then d.picture else '' end,'submitted',d.picture<>'','finishRank',d.finish_rank,'finishBonus',d.finish_bonus,'awarded',d.awarded,'winner',exists(select 1 from public.english_drawing_bonus b where b.session_id=s.id and b.round=g.round and b.artist=d.artist)) order by d.position) from public.english_drawings d join public.profiles p on p.id=d.artist where d.session_id=s.id and d.round=g.round),'[]'::jsonb),'scores',coalesce((select jsonb_agg(jsonb_build_object('id',m.learner_id,'name',coalesce(p.display_name,'Student'),'points',coalesce((select sum(d.finish_bonus) from public.english_drawings d where d.session_id=s.id and d.artist=m.learner_id),0)+(select count(*) from public.english_drawings d where d.session_id=s.id and d.awarded=m.learner_id)+3*(select count(*) from public.english_drawing_bonus b where b.session_id=s.id and b.artist=m.learner_id))) from public.english_class_members m join public.profiles p on p.id=m.learner_id where m.session_id=s.id),'[]'::jsonb));
end;$function$;
commit;
